INSERT INTO guess_who_questions (level, category, sub_category, clue1, clue2, clue3, clue4, answer, is_active) VALUES
  ('მარტივი','Football','გუნდი','დავარსდი 1902 წელს და ჩემს ისტორიაში არასდროს გავვარდნილვარ ქვეყნის უმაღლესი დივიზიონიდან.','ევროპის მთავარ საკლუბო ტურნირზე ჩემპიონობა ზედიზედ ხუთჯერ მაქვს მოპოვებული ტურნირის დაარსების პირველ წლებში.','ჩემი საშინაო არენა „სანტიაგო ბერნაბეუა“ და ტრადიციულად თეთრი ფორმით ვთამაშობ.','ვარ ჩემპიონთა ლიგის ყველაზე ტიტულოვანი კლუბი და „სამეფო კლუბის“ სახელით მიცნობენ.','მადრიდის „რეალი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1899 წელს შვეიცარიელი ჟოან გამპერის თაოსნობით.','2009 წელს გავხდი პირველი ესპანური კლუბი, რომელმაც ერთ სეზონში „ტრებლი“ შეასრულა, ხოლო კალენდარულ წელს ექვსივე ტიტული მოიგო.','ჩემი აკადემია „ლა მასია“ მსოფლიოში ერთ-ერთი ყველაზე ცნობილი საფეხბურთო სკოლაა.','ჩემი სტადიონი „კამპ ნოუა“, ხოლო ჩემი დევიზია — „მეტი ვიდრე კლუბი“ (Més que un club).','„ბარსელონა“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1900 წელს, თუმცა ჩემი პირველი ეროვნული ჩემპიონობა 1932 წელს მოვიპოვე.','2013 და 2020 წლებში შევძელი ერთ სეზონში „ტრებლის“ შესრულება (ჩემპიონატი, თასი და ჩემპიონთა ლიგა).','ჩემი საშინაო არენა „ალიანც არენაა“, ხოლო ჩემი ტრადიციული ფერები წითელი და თეთრია.','ვარ გერმანიის ყველაზე ტიტულოვანი კლუბი და რეკორდმაისტერს მეძახიან.','მიუნხენის „ბაიერნი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1892 წელს მას შემდეგ, რაც „ევერტონმა“ სტადიონი „ენფილდი“ დატოვა.','2005 წელს სტამბოლში გამართულ ჩემპიონთა ლიგის ფინალში „მილანს“ 0:3-ის შემდეგ თამაში შევუტრიალე და პენალტებით მოვუგე.','ჩემი კლუბის ჰიმნია ლეგენდარული სიმღერა „You''ll Never Walk Alone“.','ვარ ინგლისის ერთ-ერთი ყველაზე ტიტულოვანი კლუბი და ჩემპიონთა ლიგა ექვსჯერ მაქვს მოგებული.','„ლივერპული“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1878 წელს რკინიგზის მუშების მიერ, თავდაპირველი სახელით „ნიუტონ ჰითი“.','1999 წელს გავხდი პირველი ინგლისური კლუბი, რომელმაც ერთ სეზონში პრემიერ ლიგა, ასოციაციის თასი და ჩემპიონთა ლიგა მოიგო.','26 წლის განმავლობაში ჩემი მთავარი მწვრთნელი ლეგენდარული სერ ალექს ფერგიუსონი იყო.','ვთამაშობ „ოლდ ტრაფორდზე“ და მეტსახელად „წითელ ეშმაკებს“ მეძახიან.','მანჩესტერ იუნაიტედი',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1970 წელს ორი ადგილობრივი კლუბის გაერთიანების შედეგად, რითაც ტოპ 5 ლიგის გრანდებს შორის ერთ-ერთი ყველაზე ახალგაზრდა კლუბი ვარ.','ჩემს რიგებში სხვადასხვა დროს უთამაშიათ რონალდინიოს, ზლატან იბრაჰიმოვიჩს, ნეიმარს, ლიონელ მესის, კილიან მბაპესა და ხვიჩა კვარაცხელიას.','ვარ საფრანგეთის ლიგა 1-ის ყველაზე ტიტულოვანი კლუბი.','საფრანგეთის დედაქალაქს წარმოვადგენ და ჩემი სტადიონი „პარკ დე პრენსია“.','„პარი სენ-ჟერმენი“ (პსჟ)',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1897 წელს ტურინელი სტუდენტების მიერ, თავდაპირველად კი ვარდისფერი ფორმით ვთამაშობდი.','ვარ იტალიის სერია A-ს ყველაზე ტიტულოვანი კლუბი და 36 ოფიციალური სკუდეტო მაქვს მოპოვებული.','ჩემი ტრადიციული ფორმა შავ-თეთრი ზოლებისგან შედგება.','მეტსახელად „ბებერ ქალბატონს“ (La Vecchia Signora) მეძახიან და ჩემი სტადიონი „ალიანც სტედიუმია“.','ტურინის „იუვენტუსი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1899 წელს ინგლისელი ემიგრანტების, ჰერბერტ კილპინისა და ალფრედ ედვარდსის მიერ.','ჩემპიონთა თასი/ლიგა შვიდჯერ მაქვს მოგებული, რაც იტალიურ კლუბებს შორის საუკეთესო შედეგია.','ჩემი ტრადიციული ფერები წითელი და შავია, ხოლო საშინაო მატჩებს „სან სიროზე“ ვმართავ.','მეტსახელად „როსონერის“ მეძახიან.','„მილანი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1908 წელს მას შემდეგ, რაც კლუბის დამფუძნებლებმა უცხოელი ფეხბურთელების მიღებაზე შეთანხმებას ვერ მიაღწიეს.','2010 წელს ჟოზე მოურინიოს ხელმძღვანელობით გავხდი პირველი და ჯერჯერობით ერთადერთი იტალიური კლუბი, რომელმაც ერთ სეზონში „ტრებლი“ შეასრულა.','ვარ ერთადერთი იტალიური კლუბი, რომელიც არასდროს გავარდნილა სერია A-დან.','ჩემი ფერები შავი და ლურჯია, ხოლო მეტსახელად „ნერაძურის“ მეძახიან.','მილანის „ინტერი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1886 წელს სამეფო არსენალის მუშების მიერ, თავდაპირველი სახელით „დაიალ სკვერი“ (Dial Square).','ვარ ერთადერთი კლუბი ინგლისის პრემიერ ლიგის ისტორიაში, რომელმაც მთელი 38-მატჩიანი სეზონი (2003–04) წაუგებლად ჩაატარა და ოქროს თასი მოიგო.','22 წლის განმავლობაში ჩემი მთავარი მწვრთნელი ფრანგი არსენ ვენგერი იყო.','ვმდებარეობ ჩრდილოეთ ლონდონში, ვთამაშობ „ემირეითსის“ სტადიონზე და მეტსახელად „მეთოფეებს“ მეძახიან.','ლონდონის „არსენალი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1905 წელს და ჩემი საშინაო სტადიონი ყოველთვის „სტემფორდ ბრიჯი“ იყო.','ჩემპიონთა ლიგა ორჯერ მაქვს მოგებული — პირველად 2012 წელს მიუნხენში და მეორედ 2021 წელს პორტუში.','ჩემს რიგებში სხვადასხვა დროს უთამაშიათ ფრენკ ლემპარდს, ჯონ ტერის, დიდიე დროგბასა და ედენ აზარს.','ლონდონური კლუბი ვარ, ტრადიციულად ლურჯი ფორმით ვთამაშობ და მეტსახელად „არისტოკრატებს“ ან „ლურჯებს“ მეძახიან.','ლონდონის „ჩელსი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1903 წელს ბასკი სტუდენტების მიერ, თავდაპირველად როგორც ბილბაოს „ატლეტიკის“ ფილიალი.','ჩემი მთავარი მწვრთნელი 2011 წლიდან არგენტინელი დიეგო სიმეონეა.','ორჯერ ვითამაშე ჩემპიონთა ლიგის ფინალში (2014 და 2016 წლებში), თუმცა ორივეჯერ თანაქალაქელ „რეალთან“ დავმარცხდი.','ვთამაშობ წითელ-თეთრ ზოლიანი მაისურებით და მადრიდის მეორე დიდი კლუბი ვარ.','მადრიდის „ატლეტიკო“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1909 წელს და ჩემი საშინაო არენა „სიგნალ იდუნა პარკი“ ცნობილია „ყვითელი კედლის“ ტრიბუნით.','1997 წელს ჩემპიონთა ლიგა მოვიგე, ხოლო 2013 და 2024 წლებში ფინალში ვითამაშე.','ჩემს რიგებში მსოფლიო ვარსკვლავებად ჩამოყალიბდნენ რობერტ ლევანდოვსკი, ერლინგ ჰოლანდი და ჯუდ ბელინგემი.','ვარ გერმანული კლუბი, რომელიც ყვითელ-შავ ფერებში თამაშობს და მიუნხენის „ბაიერნის“ მთავარი მეტოქეა.','დორტმუნდის „ბორუსია“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1880 წელს წმინდა მარკოზის ეკლესიის წევრების მიერ, თავდაპირველი სახელით „სენტ მარკსი“.','2012 წელს 44-წლიანი პაუზის შემდეგ ბოლო წამზე გატანილი გოლით მოვიგე ინგლისის ჩემპიონატი.','2022–23 წლების სეზონში პეპ გვარდიოლას ხელმძღვანელობით შევასრულე „ტრებლი“ და პირველად მოვიგე ჩემპიონთა ლიგა.','ვთამაშობ ცისფერი ფორმით, ჩემი სტადიონი „ეტიჰადია“ და ინგლისური ფეხბურთის ბოლო წლების დომინანტი გუნდი ვარ.','„მანჩესტერ სიტი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1874 წელს ბირმინგემში, წმინდა პეტრეს ეკლესიის წევრების მიერ.','1982 წელს როტერდამში მიუნხენის „ბაიერნი“ დავამარცხე და ჩემს ისტორიაში ერთადერთხელ მოვიგე ევროპის ჩემპიონთა თასი.','ჩემი საშინაო არენა „ვილა პარკია“, ხოლო ჩემი ტრადიციული ფერები შინდისფერი და ცისფერია.','ვარ ერთ-ერთი უძველესი ინგლისური კლუბი, რომელსაც ბოლო წლებში ესპანელი უნაი ემერი წვრთნის.','„ასტონ ვილა“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1882 წელს კრიკეტის კლუბის წევრების მიერ და ჩემს ემბლემაზე ბურთზე მდგარი მამალია გამოსახული.','1961 წელს გავხდი მე-20 საუკუნის პირველი ინგლისური კლუბი, რომელმაც ერთ სეზონში ინგლისის ჩემპიონატი და ასოციაციის თასი („დუბლი“) მოიგო.','2019 წელს მადრიდში გამართულ ჩემპიონთა ლიგის ფინალში ვითამაშე, თუმცა „ლივერპულთან“ დავმარცხდი.','ჩრდილოეთ ლონდონური კლუბი ვარ, თეთრი მაისურებით ვთამაშობ და „არსენალის“ მთავარი მეტოქე ვარ.','ლონდონის „ტოტენჰემ ჰოტსპური“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1904 წელს გერმანიის გელზენკირხენის ქვანახშირის მაღაროელთა რაიონში, რის გამოც მეტსახელად „მეშახტეებს“ მეძახიან.','შვიდჯერ მაქვს მოგებული გერმანიის ჩემპიონატი და 1997 წელს უეფას თასის გამარჯვებული გავხდი.','ჩემი აკადემიიდან გამოვიდნენ მანუელ ნოიერი, მესუთ ოზილი, ლეროი სანე და იულეან დრაქსლერი.','ვთამაშობ სამეფო ლურჯი ფერის მაისურებით და დორტმუნდის „ბორუსიასთან“ ერთად რურის დერბის მონაწილე ვარ.','„შალკე 04“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1904 წელს გერმანიაში, საფარმაცევტო კომპანია „ბაიერის“ თანამშრომლების მიერ.','2002 წელს სამ ტურნირში (ბუნდესლიგა, თასი, ჩემპიონთა ლიგა) მეორე ადგილი დავიკავე, რის გამოც მეტსახელად „ნევერკუზენი“ შემარქვეს.','2023–24 წლების სეზონში ჩაბი ალონსოს ხელმძღვანელობით ისტორიაში პირველად მოვიგე გერმანიის ბუნდესლიგა, თანაც მთელი სეზონი წაუგებლად ჩავატარე.','ჩემი სტადიონი „ბაიარენაა“ და გერმანული „ფარმაცევტების“ სახელით მიცნობენ.','ლევერკუზენის „ბაიერი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1927 წელს სამი ადგილობრივი კლუბის გაერთიანების შედეგად, რათა იტალიის დედაქალაქს ძლიერი გუნდი ჰყოლოდა.','ჩემი ტრადიციული ფერები ყვითელი და მუქი წითელია (ჯალოროსი), ხოლო ემბლემაზე ძუ მგელია გამოსახული.','ჩემი ლეგენდარული კაპიტანი ფრანჩესკო ტოტი იყო, ხოლო 2022 წელს უეფას კონფერენს ლიგის პირველი გათამაშება მოვიგე.','საშინაო მატჩებს „სტადიო ოლიმპიკოზე“ ვმართავ და „ლაციოს“ მთავარი მეტოქე ვარ.','„რომა“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1926 წელს და იტალიის სამხრეთის ყველაზე პოპულარული საფეხბურთო კლუბი ვარ.','1987 და 1990 წლებში დიეგო მარადონას ლიდერობით ჩემს ისტორიაში პირველი ორი სკუდეტო მოვიგე.','2022–23 წლების სეზონში ხვიჩა კვარაცხელიასა და ვიქტორ ოსიმენის ლიდერობით 33-წლიანი პაუზის შემდეგ კვლავ გავხდი იტალიის ჩემპიონი.','ვთამაშობ ცისფერი ფორმით და ჩემი სტადიონი დიეგო არმანდო მარადონას სახელს ატარებს.','„ნაპოლი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1900 წელს რომში და ჩემი ემბლემა არწივია, რომელიც რომის იმპერიის სიმბოლო იყო.','ორჯერ მაქვს მოგებული იტალიის სერია A (1974 და 2000 წლებში), ხოლო 1999 წელს მოვიგე თასების მფლობელთა თასის ბოლო გათამაშება.','ჩემი ტრადიციული ფერები ცისფერი და თეთრია (ბიანკოჩელესტი).','საშინაო მატჩებს „სტადიო ოლიმპიკოზე“ ვმართავ და „რომასთან“ ერთად დერბი დელა კაპიტალეს ვთამაშობ.','რომის „ლაციო“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1890 წელს ესპანეთის სამხრეთში და ქვეყნის უძველესი საფეხბურთო კლუბი ვარ, რომელიც სრულად მხოლოდ ფეხბურთზე იყო ორიენტირებული.','ევროპის ლიგის (ყოფილი უეფას თასის) ისტორიაში ყველაზე ტიტულოვანი კლუბი ვარ — ეს ტურნირი რეკორდულად, შვიდჯერ მაქვს მოგებული.','ჩემი საშინაო არენა „რამონ სანჩეს პისხუანია“ და თეთრ-წითელ ფერებში ვთამაშობ.','ანდალუსიის დედაქალაქს წარმოვადგენ და „რეალ ბეტისის“ მთავარი მეტოქე ვარ.','„სევილია“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1898 წელს ბასკეთში და 1929 წლიდან მოყოლებული არასდროს გავვარდნილვარ ესპანეთის უმაღლესი დივიზიონიდან.','ცნობილი ვარ უნიკალური სატრანსფერო პოლიტიკით — ჩემს გუნდში მხოლოდ ბასკი ფეხბურთელები თამაშობენ.','ესპანეთის სამეფო თასი (Copa del Rey) 24-ჯერ მაქვს მოგებული, მათ შორის 2024 წელს, 40-წლიანი პაუზის შემდეგ.','ჩემი სტადიონი „სან მამესია“ და ტრადიციულად წითელ-თეთრ ზოლიანი მაისურებით ვთამაშობ.','ბილბაოს „ატლეტიკი“',true),
  ('მარტივი','Football','გუნდი','1978 წელს გავხდი პირველი გერმანული კლუბი, რომელმაც ერთ სეზონში გერმანიის ჩემპიონატი და თასი („დუბლი“) მოიგო.','ვარ ერთადერთი კლუბი გერმანიაში, რომელმაც ბუნდესლიგის დაარსების (1963) პირველ სეზონში ჩემპიონობა მოიპოვა.','ჩემი საშინაო არენა „რეინენერგიშტადიონია“, ხოლო ჩემი სიმბოლო და ცოცხალი თილისმა თხა სახელად „ჰენესია“.','ვმდებარეობ გერმანიის ერთ-ერთ უძველეს ქალაქში და წითელ-თეთრ ფერებში ვთამაშობ.','„კიოლნი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1900 წელს ნიდერლანდების დედაქალაქში.','1971–1973 წლებში ზედიზედ სამჯერ მოვიგე ევროპის ჩემპიონთა თასი და მსოფლიოს „ტოტალური ფეხბურთი“ გავაცანი.','ჩემი აკადემიიდან გამოვიდნენ იოჰან კრუიფი, მარკო ვან ბასტენი, დენის ბერგკამპი და ფრენკი დე იონგი.','ჩემი სტადიონი იოჰან კრუიფის სახელს ატარებს და ლეგენდარული ბერძენი გმირის სახელი მქვია.','ამსტერდამის „აიაქსი“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1904 წელს პორტუგალიის დედაქალაქში.','1961 და 1962 წლებში ეუსებიოს ლიდერობით ზედიზედ ორჯერ მოვიგე ევროპის ჩემპიონთა თასი.','1962 წელს ჩემმა ყოფილმა მწვრთნელმა ბელა გუტმანმა დამწყევლა, რომ 100 წლის განმავლობაში ევროპულ ფინალს ვერ მოვიგებდი, რის შემდეგაც 8 ევროპული ფინალი წავაგე.','ვთამაშობ წითელი ფორმით, ჩემი სტადიონი „ესტადიო და ლუშია“ და მატჩების წინ არწივი დაფრინავს მოედანზე.','ლისაბონის „ბენფიკა“',true),
  ('მარტივი','Football','გუნდი','დავარსდი 1893 წელს ჩრდილოეთ პორტუგალიაში და ქვეყნის ერთ-ერთი უძველესი კლუბი ვარ.','2004 წელს ჟოზე მოურინიოს ხელმძღვანელობით სენსაციურად მოვიგე ჩემპიონთა ლიგა, ხოლო მანამდე 1987 წელსაც გავხდი ევროპის ჩემპიონი.','ჩემი საშინაო არენა „ესტადიო დუ დრაგაუა“ და ლურჯ-თეთრ ზოლიანი მაისურებით ვთამაშობ.','მეტსახელად „დრაკონებს“ მეძახიან.','„პორტუ“',true),
  ('მარტივი','Football','მსაჯი','მსაჯობა 1977 წელს იტალიაში დავიწყე და სერია A-ში პირველად 1991 წელს ვიმსაჯე.','ვიყავი მთავარი არბიტრი 1999 წლის ჩემპიონთა ლიგის ლეგენდარულ ფინალში „მანჩესტერ იუნაიტედსა“ და „ბაიერნს“ შორის.','ასევე ვიმსაჯე 2002 წლის მსოფლიო ჩემპიონატის ფინალი ბრაზილიასა და გერმანიას შორის.','ზედიზედ ექვსჯერ დამასახელეს მსოფლიოს საუკეთესო მსაჯად და ყველას უთმო თავითა და მკაცრი გამოხედვით ვამახსოვრდები.','პიერლუიჯი კოლინა',true),
  ('მარტივი','Football','მსაჯი','მსაჯობა ინგლისში 1989 წელს დავიწყე, ხოლო პრემიერ ლიგაში 2003 წლიდან ვმსაჯობდი.','2010 წელს გავხდი პირველი მსაჯი ისტორიაში, რომელმაც ერთსა და იმავე წელს იმსაჯა ჩემპიონთა ლიგისა და მსოფლიო ჩემპიონატის ფინალები.','2010 წლის მუნდიალის ფინალში ესპანეთსა და ნიდერლანდებს შორის რეკორდული რაოდენობის, 14 ყვითელი ბარათი ვაჩვენე.','ვარ ინგლისელი ყოფილი პოლიციელი და ცნობილი არბიტრი.','ჰოვარდ უები',true),
  ('მარტივი','Football','მწვრთნელი','საფეხბურთო კარიერის შემდეგ მწვრთნელობა შოტლანდიურ „ისტ სტირლინგშირსა“ და „აბერდინში“ დავიწყე, სადაც 1983 წელს თასების მფლობელთა თასი მოვიგე.','1986 წლიდან 2013 წლამდე, 26 წლის განმავლობაში ვწვრთნიდი ერთ ინგლისურ გრანდს.','ჩემს გუნდს მოვაგებინე 13 პრემიერ ლიგის ტიტული და ორჯერ ჩემპიონთა ლიგა (1999 და 2008 წლებში).','ვარ შოტლანდიელი ლეგენდარული მწვრთნელი, რომელმაც „მანჩესტერ იუნაიტედი“ მსოფლიო ფეხბურთის მწვერვალზე აიყვანა.','სერ ალექს ფერგიუსონი',true),
  ('მარტივი','Football','მწვრთნელი','სამწვრთნელო კარიერა „ბარსელონა B“-ში დავიწყე, ხოლო 2008 წელს მთავარი გუნდი ჩავიბარე და პირველივე სეზონში „ტრებლი“ მოვიგე.','გავწვრთენი ესპანეთის, გერმანიისა და ინგლისის ჩემპიონი გუნდები — „ბარსელონა“, „ბაიერნი“ და „მანჩესტერ სიტი“.','ვარ პირველი მწვრთნელი ფეხბურთის ისტორიაში, რომელმაც ორ სხვადასხვა კლუბთან ერთად შეასრულა „ტრებლი“ (2009 და 2023 წლებში).','ცნობილი ვარ „ტიკი-ტაკას“ სათამაშო სტილითა და „მანჩესტერ სიტიში“ მოპოვებული დომინაციით.','პეპ გვარდიოლა',true),
  ('მარტივი','Football','მწვრთნელი','როგორც ფეხბურთელმა, ორჯერ მოვიგე ჩემპიონთა თასი „მილანის“ შემადგენლობაში (1989 და 1990 წლებში).','ვარ ერთადერთი მწვრთნელი ისტორიაში, რომელმაც ევროპის ხუთივე ტოპ ლიგის ჩემპიონობა მოიგო (იტალია, ინგლისი, საფრანგეთი, გერმანია და ესპანეთი).','მთავარი მწვრთნელის რანგში რეკორდული რაოდენობის, 5 ჩემპიონთა ლიგის თასი მაქვს მოგებული („მილანთან“ და მადრიდის „რეალთან“ ერთად).','ვარ იტალიელი მწვრთნელი, რომელსაც „პაპა კარლოს“ ეძახიან და წარბის აწევითაა ცნობილი.','კარლო ანჩელოტი',true),
  ('მარტივი','Football','მწვრთნელი','სამწვრთნელო კარიერა გერმანულ „მაინც 05“-ში დავიწყე, სადაც მანამდე 11 წელი ფეხბურთელად ვთამაშობდი.','დორტმუნდის „ბორუსიას“ ზედიზედ ორჯერ მოვაგებინე გერმანიის ბუნდესლიგა (2011 და 2012 წლებში) და 2013 წელს ჩემპიონთა ლიგის ფინალში გავიყვანე.','2019 წელს „ლივერპულთან“ ერთად ჩემპიონთა ლიგა მოვიგე, ხოლო 2020 წელს კლუბს 30-წლიანი პაუზის შემდეგ ინგლისის ჩემპიონობა მოვუტანე.','ვარ გერმანელი მწვრთნელი, რომელიც ემოციური ქცევით, სათვალითა და გამარჯვების შემდეგ ტრიბუნებისკენ სამი მუშტის მოქნევით იყო ცნობილი.','იურგენ კლოპი',true),
  ('მარტივი','Football','მწვრთნელი','2004 წელს პორტუგალიურ „პორტუსთან“ ერთად სენსაციურად მოვიგე ჩემპიონთა ლიგა.','ვარ პირველი მწვრთნელი, რომელმაც უეფას სამივე საკლუბო ტურნირი მოიგო — ჩემპიონთა ლიგა, ევროპა ლიგა და კონფერენს ლიგა.','ინგლისურ „ჩელსიში“ მისვლისას პრესკონფერენციაზე საკუთარ თავს „განსაკუთრებული“ (The Special One) ვუწოდე.','ვარ პორტუგალიელი მწვრთნელი, რომელსაც „ინტერში“, მადრიდის „რეალში“, „მანჩესტერ იუნაიტედსა“ და „რომაშიც“ უმუშავია.','ჟოზე მოურინიო',true),
  ('მარტივი','Football','მწვრთნელი','სამწვრთნელო კარიერის სტარტზე ვმუშაობდი „ნანსისა“ და „მონაკოში“, ხოლო 1995–96 წლებში იაპონურ „ნაგოია გრამპუსს“ ვწვრთნიდი.','1996 წლიდან 2018 წლამდე, 22 წლის განმავლობაში ვიყავი ერთი ლონდონური კლუბის მთავარი მწვრთნელი.','2003–04 წლების სეზონში ჩემმა გუნდმა ინგლისის პრემიერ ლიგა წაუგებლად მოიგო.','ვარ ფრანგი მწვრთნელი, რომელსაც ლონდონის „არსენალში“ „პროფესორს“ ეძახდნენ.','არსენ ვენგერი',true),
  ('მარტივი','Football','ფეხბურთელი','2006 წელს იტალიის ეროვნულ ნაკრებს ვუკაპიტნე და ბერლინში მსოფლიო ჩემპიონი გავხდი.','2006 წელს გავხდი პირველი მცველი, რომელმაც მოიგო როგორც „ოქროს ბურთი“, ისე ფიფას წლის საუკეთესო ფეხბურთელის ჯილდო.','საკლუბო კარიერის განმავლობაში მითამაშია „ნაპოლიში“, „პარმაში“, „ინტერში“, „იუვენტუსსა“ და მადრიდის „რეალში“.','ვარ იტალიელი ცენტრალური მცველი, რომელსაც მეტსახელად „Il Muro di Berlino“-ს (ბერლინის კედელს) ეძახდნენ.','ფაბიო კანავარო',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1957 წელს და ვუმასპინძლე 1982 წლის მსოფლიო ჩემპიონატის გახსნის მატჩს.','1999 წელს ჩემს მოედანზე გაიმართა ჩემპიონთა ლიგის ფინალი, სადაც „მანჩესტერ იუნაიტედმა“ „ბაიერნი“ დაამარცხა.','რეკონსტრუქციამდე დაახლოებით 99 000 მაყურებელს ვიტევდი და ევროპის ყველაზე დიდი საფეხბურთო სტადიონი ვარ.','კატალონიის დედაქალაქში ვმდებარეობ და „ბარსელონას“ საშინაო არენა ვარ.','კამპ ნოუ',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1947 წელს და 1982 წლის მსოფლიო ჩემპიონატის ფინალს ვუმასპინძლე.','ჩემს მოედანზე ოთხჯერ გაიმართა ჩემპიონთა თასის/ლიგის ფინალი, მათ შორის 2010 წელს.','სახელი კლუბის ლეგენდარული ყოფილი ფეხბურთელისა და პრეზიდენტის პატივსაცემად დამერქვა.','ესპანეთის დედაქალაქში ვმდებარეობ და მადრიდის „რეალის“ საშინაო არენა ვარ.','სანტიაგო ბერნაბეუ',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1884 წელს და თავდაპირველად სხვა ლივერპულური კლუბის — „ევერტონის“ საშინაო არენა ვიყავი.','ჩემი ერთ-ერთი ყველაზე ცნობილი ტრიბუნაა „The Kop“, რომელიც გამორჩეული ატმოსფეროთია ცნობილი.','მოედანზე გასასვლელ გვირაბში კიდია ცნობილი წარწერა — „This Is Anfield“.','ვარ „ლივერპულის“ საშინაო სტადიონი.','ენფილდი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 2005 წელს და ვუმასპინძლე 2006 წლის მსოფლიო ჩემპიონატის გახსნის მატჩს გერმანიასა და კოსტა-რიკას შორის.','ჩემი ფასადი შედგება ათასობით გასაბერი პანელისგან, რომლებიც ფერს იცვლიან იმის მიხედვით, თუ რომელი გუნდი თამაშობს.','2012 და 2025 წლებში ჩემს მოედანზე გაიმართა ჩემპიონთა ლიგის ფინალი.','ვმდებარეობ გერმანიაში და მიუნხენის „ბაიერნის“ საშინაო არენა ვარ.','ალიანც არენა',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1926 წელს და თავდაპირველად მხოლოდ ერთი კლუბის საშინაო არენა ვიყავი, ხოლო 1947 წლიდან ორი მეტოქე გუნდი მიყოფს.','ვუმასპინძლე 1934 და 1990 წლების მსოფლიო ჩემპიონატის მატჩებს, ასევე ოთხჯერ — ჩემპიონთა ლიგის ფინალს.','ოფიციალურად ვატარებ ლეგენდარული იტალიელი ფეხბურთელის, ჯუზეპე მეაცას სახელს.','ვმდებარეობ იტალიაში და ვარ „მილანისა“ და „ინტერის“ საშინაო სტადიონი.','სან სირო (ჯუზეპე მეაცა)',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1923 წელს და თავდაპირველად „იმპერიის სტადიონის“ (Empire Stadium) სახელით ვიყავი ცნობილი, ხოლო 2007 წელს სრულიად ახალი არენა აშენდა ჩემს ადგილას.','ჩემს მოედანზე გაიმართა 1966 წლის მსოფლიო ჩემპიონატის ფინალი, სადაც ინგლისმა გერმანია დაამარცხა.','90 000 მაყურებელს ვიტევ და დიდი ბრიტანეთის ყველაზე დიდი სტადიონი ვარ.','ვმდებარეობ ლონდონში, გამოვირჩევი გიგანტური თაღით და ინგლისის ეროვნული ნაკრების საშინაო არენა ვარ.','უემბლი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1910 წელს და ვუმასპინძლე 1966 წლის მსოფლიო ჩემპიონატის ჯგუფური ეტაპის მატჩებს.','2003 წელს ჩემს მოედანზე გაიმართა ჩემპიონთა ლიგის ფინალი, რომელშიც „მილანმა“ „იუვენტუსი“ პენალტების სერიაში დაამარცხა.','დაახლოებით 74 000 გულშემატკივარს ვიტევ და „უემბლის“ შემდეგ ინგლისის ყველაზე დიდი საფეხბურთო სტადიონი ვარ.','ბობი ჩარლტონმა მეტსახელად „ოცნებების თეატრი“ მიწოდა და „მანჩესტერ იუნაიტედის“ საშინაო არენა ვარ.','ოლდ ტრაფორდი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 2006 წელს და ლონდონში ჩემი წინამორბედი ლეგენდარული სტადიონი „ჰაიბერი“ შევცვალე.','დაახლოებით 60 700 მაყურებელს ვიტევ და ჩემს შესასვლელთან არსენ ვენგერის, ტიერი ანრისა და დენის ბერგკამპის ძეგლები დგას.','ჩემი სახელი არაბული ავიაკომპანიის სპონსორობას უკავშირდება.','ვარ ლონდონის „არსენალის“ საშინაო სტადიონი.','ემირეითსი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1974 წელს და ვუმასპინძლე 1974 და 2006 წლების მსოფლიო ჩემპიონატის მატჩებს.','ჩემს ტრიბუნებზე 81 365 მაყურებელი ეტევა და გერმანიის ყველაზე დიდი საფეხბურთო სტადიონი ვარ.','ჩემი სამხრეთ ტრიბუნა ცნობილია როგორც „ყვითელი კედელი“ (Die Gelbe Wand), რომელიც 25 000 ფეხზე მდგომ ფანს იტევს.','ვარ დორტმუნდის „ბორუსიას“ საშინაო არენა.','სიგნალ იდუნა პარკი (ვესტფალენშტადიონი)',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1972 წელს საფრანგეთში და ჩემს მოედანზე გაიმართა 1984 წლის ევროპის ჩემპიონატის ფინალი.','სახელი ფრანგულად „პრინცების პარკს“ ნიშნავს, რადგან მე-18 საუკუნეში აქ სამეფო სანადირო ტყე იყო.','1974 წლიდან მოყოლებული საფრანგეთის ყველაზე ტიტულოვანი კლუბის საშინაო არენა ვარ.','ვმდებარეობ პარიზში და „პარი სენ-ჟერმენის“ საშინაო სტადიონი ვარ.','პარკ დე პრენსი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1998 წელს სპეციალურად საფრანგეთში გამართული მსოფლიო ჩემპიონატისთვის.','ჩემს მოედანზე გაიმართა 1998 წლის მუნდიალის ფინალი, სადაც საფრანგეთმა ბრაზილია 3:0 დაამარცხა.','ასევე ვუმასპინძლე 2016 წლის ევროპის ჩემპიონატის ფინალს და სამჯერ ჩემპიონთა ლიგის ფინალს (2000, 2006, 2022).','დაახლოებით 80 000 მაყურებელს ვიტევ და საფრანგეთის ეროვნული სტადიონი ვარ.','სტად დე ფრანსი',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1953 წელს და ვუმასპინძლე 1960 წლის ზაფხულის ოლიმპიურ თამაშებს.','ჩემს მოედანზე გაიმართა 1990 წლის მსოფლიო ჩემპიონატის ფინალი, ასევე 1968, 1980 და 2020 წლების ევროპის ჩემპიონატის ფინალები.','დაახლოებით 70 000 მაყურებელს ვიტევ და ორ დედაქალაქურ კლუბს ვემსახურები.','ვმდებარეობ რომში და ვარ „რომასა“ და „ლაციოს“ საშინაო სტადიონი.','სტადიო ოლიმპიკო',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 2017 წელს ახალი სახით და 2019 წელს ვუმასპინძლე ჩემპიონთა ლიგის ფინალს „ლივერპულსა“ და „ტოტენჰემს“ შორის.','ჩემს ტრიბუნებზე 70 000-ზე მეტი გულშემატკივარი ეტევა და შევცვალე ძველი ლეგენდარული არენა „ვისენტე კალდერონი“.','ვმდებარეობ ესპანეთის დედაქალაქის აღმოსავლეთ ნაწილში.','ვარ მადრიდის „ატლეტიკოს“ საშინაო სტადიონი.','მეტროპოლიტანო (ვანდა/სივიტას/რიად ეარ მეტროპოლიტანო)',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1950 წელს სპეციალურად ბრაზილიაში გამართული მსოფლიო ჩემპიონატისთვის.','1950 წლის მუნდიალის გადამწყვეტ მატჩს ჩემს ტრიბუნებზე დაახლოებით 200 000 ადამიანი დაესწრო, რაც ფეხბურთის ისტორიაში რეკორდია.','ასევე ვუმასპინძლე 2014 წლის მსოფლიო ჩემპიონატის ფინალს და 2016 წლის ოლიმპიური თამაშების გახსნის ცერემონიას.','ვმდებარეობ რიო-დე-ჟანეიროში და მსოფლიო ფეხბურთის ერთ-ერთი ყველაზე ლეგენდარული არენა ვარ.','მარაკანა',true),
  ('მარტივი','Football','სტადიონი','გავიხსენი 1940 წელს არგენტინის დედაქალაქში და გამორჩეული ვარ სწორი, ვერტიკალური ტრიბუნებით, რომლებიც მოედანს ზემოდან დაჰყურებს.','ჩემი ფორმის გამო შოკოლადის ყუთს მიმსგავსეს და სწორედ აქედან მომდინარეობს ჩემი ცნობილი მეტსახელი.','გულშემატკივრების ხტუნვის დროს ჩემი ტრიბუნები ვიბრირებს, რის გამოც ამბობენ, რომ „სტადიონი სუნთქავს“.','ვმდებარეობ ბუენოს-აირესში და „ბოკა ხუნიორსის“ საშინაო არენა ვარ.','ლა ბომბონერა',true),
  ('მარტივი','Football','ფეხბურთელი','საკლუბო კარიერის განმავლობაში ესპანეთის ლა ლიგის 10 ტიტული და ჩემპიონთა ლიგის 4 თასი მაქვს მოგებული.','ესპანეთის ჩემპიონატში გატანილი 474 გოლით ტურნირის ყველა დროის საუკეთესო ბომბარდირი ვარ.','2022 წელს კატარში გამართულ მსოფლიო ჩემპიონატზე ჩემს ეროვნულ ნაკრებს ვუკაპიტნე და ტურნირის გამარჯვებული გავხდი.','„ბარსელონას“ ლეგენდა ვარ და ისტორიაში რეკორდული რაოდენობის, 8 „ოქროს ბურთი“ მაქვს მოგებული.','ლიონელ მესი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ლისაბონის „სპორტინგში“ დავიწყე და 2003 წელს ინგლისურ გრანდში გადავედი.','ინგლისის პრემიერ ლიგაში „მანჩესტერ იუნაიტედის“ მაისურით ორი სხვადასხვა პერიოდი გავატარე და 100-ზე მეტი გოლი გავიტანე.','ვარ პორტუგალიის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი და 2016 წლის ევროპის ჩემპიონი.','ჩემი საფირმო გოლის აღნიშვნისას ჰაერში ვხტები, ვტრიალდები და სტადიონთან ერთად ვყვირი „Siuuu!“.','კრიშტიანუ რონალდუ',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ბრაზილიურ „სანტოსში“ დავიწყე და 2011 წელს კოპა ლიბერტადორესი მოვიგე.','2017 წელს ფეხბურთის ისტორიაში რეკორდული თანხის, 222 მილიონი ევროს სანაცვლოდ „პარი სენ-ჟერმენში“ გადავედი.','„ბარსელონაში“ თამაშისას ლიონელ მესისთან და ლუის სუარესთან ერთად ლეგენდარულ შემტევ ტრიოს (MSN) ვქმნიდი.','ვარ ბრაზილიის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი და 2025 წელს კვლავ მშობლიურ „სანტოსში“ დავბრუნდი.','ნეიმარი',true),
  ('მარტივი','Football','ფეხბურთელი','პროფესიონალური კარიერა ფრანგულ „მონაკოში“ დავიწყე და 2016–17 წლების სეზონში საფრანგეთის ჩემპიონი გავხდი.','2018 წელს მსოფლიო ჩემპიონი გავხდი, ხოლო 2022 წლის მუნდიალის ფინალში ჰეთ-თრიკი შევასრულე.','შვიდი სეზონი გავატარე „პარი სენ-ჟერმენში“ და კლუბის ყველა დროის საუკეთესო ბომბარდირად ვიქეცი.','2024 წელს მადრიდის „რეალში“ გადავედი და საფრანგეთის ნაკრების კაპიტანი ვარ.','კილიან მბაპე',true),
  ('მარტივი','Football','ფეხბურთელი','სანამ ტოპ 5 ლიგაში გადავიდოდი, ნორვეგიულ „მოლდესა“ და ავსტრიულ „ზალცბურგში“ ვთამაშობდი.','გერმანიის ბუნდესლიგაში დორტმუნდის „ბორუსიას“ მაისურით ჩატარებულ 67 მატჩში 62 გოლი გავიტანე.','2022–23 წლების სეზონში ინგლისის პრემიერ ლიგაში 36 გოლი გავიტანე და ერთ სეზონში გატანილი გოლების რეკორდი დავამყარე.','ვარ ნორვეგიის ნაკრების თავდამსხმელი და „მანჩესტერ სიტის“ მთავარი გოლეადორი.','ერლინგ ჰოლანდი',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპული კარიერა გერმანულ „ვერდერსა“ და ინგლისურ „ჩელსიში“ დავიწყე, სანამ „ვოლფსბურგში“ გადავიდოდი.','2019–20 წლების სეზონში პრემიერ ლიგაში 20 საგოლე გადაცემა შევასრულე და ტიერი ანრის რეკორდი გავიმეორე.','ბელგიის ეროვნულ ნაკრებში 100-ზე მეტი მატჩი ჩავატარე და „ოქროს თაობის“ მთავარი გამთამაშებელი ვიყავი.','თითქმის ათი წელი გავატარე „მანჩესტერ სიტიში“, სადაც ექვსჯერ მოვიგე პრემიერ ლიგა და 2023 წელს ჩემპიონთა ლიგა.','კევინ დე ბრუინი',true),
  ('მარტივი','Football','ფეხბურთელი','პროფესიონალური კარიერა პოლონეთში დავიწყე, ხოლო გერმანიაში პირველად დორტმუნდის „ბორუსიაში“ გავითქვი სახელი.','2015 წელს „ვოლფსბურგის“ კარში 9 წუთში 5 გოლი გავიტანე და გინესის რეკორდი დავამყარე.','მიუნხენის „ბაიერნის“ მაისურით ბუნდესლიგის ერთ სეზონში 41 გოლი გავიტანე და გერდ მიულერის რეკორდი მოვხსენი.','ვარ პოლონეთის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი და „ბარსელონას“ თავდამსხმელი.','რობერტ ლევანდოვსკი',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპაში შვეიცარიულ „ბაზელში“ გადმოვედი, ხოლო შემდეგ „ჩელსისა“ და იტალიურ კლუბებში ვთამაშობდი.','2017–18 წლების სეზონში პრემიერ ლიგაში 32 გოლი გავიტანე და 38- მატჩიანი სეზონის მაშინდელი რეკორდი დავამყარე.','ვარ ეგვიპტის ეროვნული ნაკრების კაპიტანი და აფრიკის წლის საუკეთესო ფეხბურთელის ტიტული ორჯერ მაქვს მოგებული.','„ლივერპულის“ გულშემატკივრებმა „ეგვიპტელი მეფე“ მიწოდეს და კლუბთან ერთად მოვიგე როგორც პრემიერ ლიგა, ისე ჩემპიონთა ლიგა.','მოჰამედ სალაჰი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ზაგრების „დინამოში“ დავიწყე, ხოლო 2008 წელს ლონდონის „ტოტენჰემში“ გადავედი.','2018 წელს ჩემს ეროვნულ ნაკრებს მსოფლიო ჩემპიონატის ფინალამდე ვუკაპიტნე და ტურნირის საუკეთესო ფეხბურთელი გავხდი.','იმავე 2018 წელს მოვიგე „ოქროს ბურთი“ და შევწყვიტე მესისა და რონალდუს ათწლიანი ჰეგემონია.','ვარ ხორვატიის ნაკრების ლეგენდა და მადრიდის „რეალთან“ ერთად ექვსჯერ მაქვს მოგებული ჩემპიონთა ლიგა.','ლუკა მოდრიჩი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა მშობლიური ქალაქის კლუბ „სევილიაში“ დავიწყე და 2005 წელს ესპანურ გრანდში გადავედი.','ესპანეთის ეროვნულ ნაკრებთან ერთად მოვიგე 2010 წლის მსოფლიო ჩემპიონატი და ორი ევროპის ჩემპიონატი (2008, 2012).','2014 წლის ჩემპიონთა ლიგის ფინალში 93-ე წუთზე გატანილი თავური გოლით ჩემი გუნდი დამატებით დროში გადავიყვანე.','ვარ მცველი, რომელმაც კარიერაში 100-ზე მეტი გოლი გაიტანა და მადრიდის „რეალის“ ლეგენდარული კაპიტანი იყო.','სერხიო რამოსი',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპული კარიერა ლისაბონის „ბენფიკაში“ დავიწყე, საიდანაც 2010 წელს მადრიდის „რეალში“ გადავედი.','გატანილი გოლი მაქვს 2021 წლის კოპა ამერიკის, 2022 წლის ფინალისიმასა და 2022 წლის მსოფლიო ჩემპიონატის ფინალებში.','საკლუბო დონეზე მითამაშია ისეთ კლუბებში, როგორებიც არიან „მანჩესტერ იუნაიტედი“, „პარი სენ-ჟერმენი“ და „იუვენტუსი“.','ვარ არგენტინელი შემტევი, რომელსაც თხელი აღნაგობის გამო მეტსახელად „El Fideo“-ს (ლაფშას) ეძახიან.','ანხელ დი მარია',true),
  ('მარტივი','Football','ფეხბურთელი','პროფესიონალური კარიერა „სან-პაულუში“ დავიწყე და 2003 წელს იტალიურ გრანდში გადავედი.','2002 წელს ბრაზილიის ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი.','2007 წელს „მილანთან“ ერთად ჩემპიონთა ლიგა მოვიგე და იმავე წელს „ოქროს ბურთის“ მფლობელი გავხდი.','2009 წელს მადრიდის „რეალში“ გადავედი და ჩემი ელეგანტური თამაშითა და სისწრაფით გამოვორჩეოდი.','კაკა',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპული კარიერა ნიდერლანდებში, „გრონინგენსა“ და „აიაქსში“ გავატარე, სანამ პრემიერ ლიგაში გადავიდოდი.','2013–14 წლების სეზონში „ლივერპულის“ მაისურით პრემიერ ლიგაში 31 გოლი გავიტანე და ოქროს ბუცი მოვიგე.','2015–16 წლების სეზონში ლა ლიგაში 40 გოლი გავიტანე და მესისა და რონალდუს ეპოქაში ბომბარდირი გავხდი.','ვარ ურუგვაის ნაკრების ყველა დროის საუკეთესო ბომბარდირი და მეტსახელად „El Pistolero“-ს მეძახიან.','ლუის სუარესი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ფრანგულ „ლიონში“ დავიწყე და ზედიზედ ოთხჯერ მოვიგე საფრანგეთის ჩემპიონატი.','14 სეზონი გავატარე მადრიდის „რეალში“ და კლუბის ისტორიაში მეორე საუკეთესო ბომბარდირი გავხდი.','2022 წელს, 34 წლის ასაკში, კარიერაში პირველად მოვიგე „ოქროს ბურთი“.','ვარ ფრანგი თავდამსხმელი, რომელმაც 2023 წელს კარიერა საუდის არაბეთის „ალ-იტიჰადში“ გააგრძელა.','ქარიმ ბენზემა',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ლივერპულის „ევერტონში“ დავიწყე და 16 წლის ასაკში პრემიერ ლიგაში ულამაზესი გოლი გავიტანე „არსენალის“ კარში.','წლების განმავლობაში ვიყავი ინგლისის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი 53 გოლით.','„მანჩესტერ იუნაიტედის“ ისტორიაში ყველაზე მეტი, 253 გოლი მაქვს გატანილი.','2011 წელს „მანჩესტერ სიტის“ კარში ლეგენდარული „მაკრატელა“ გოლი გავიტანე.','უეინ რუნი',true),
  ('მარტივი','Football','ფეხბურთელი','საკლუბო კარიერის სტარტზე თბილისის „დინამოში“, რუსთავის „მეტალურგსა“ და ბათუმის „დინამოში“ ვთამაშობდი.','2022–23 წლების სეზონში იტალიის სერია A-ს საუკეთესო ფეხბურთელად დასახელდი და „ნაპოლის“ 33-წლიანი პაუზის შემდეგ სკუდეტო მოვაგებინე.','2024 წელს საქართველოს ეროვნულ ნაკრებთან ერთად ისტორიაში პირველად ვითამაშე ევროპის ჩემპიონატზე და პორტუგალიას გოლი გავუტანე.','2025 წლის იანვარში „პარი სენ-ჟერმენში“ გადავედი და გულშემატკივრებმა „კვარადონა“ შემარქვეს.','ხვიჩა კვარაცხელია',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „პარმაში“ დავიწყე და 1999 წელს ამ კლუბთან ერთად უეფას თასი მოვიგე.','ჩემპიონთა ლიგის ფინალში სამჯერ ვითამაშე, მაგრამ ეს ტურნირი კარიერაში ვერასდროს მოვიგე.','2006 წელს იტალიის ეროვნულ ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი.','ვარ მეკარე, რომელმაც კარიერის უდიდესი ნაწილი ტურინის „იუვენტუსში“ გაატარა და იტალიის ნაკრებში 176 მატჩი ჩაატარა.','ჯანლუიჯი ბუფონი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა გერმანულ „შალკე 04“-ში დავიწყე და 2011 წელს გერმანიის თასი მოვიგე.','2014 წლის მსოფლიო ჩემპიონატზე გერმანიის ნაკრებთან ერთად ოქროს მედალი მოვიპოვე და ტურნირის საუკეთესო მეკარედ დავსახელდი.','საფეხბურთო სამყაროში დავამკვიდრე „მეკარე-ლიბეროს“ (Sweeper-keeper) თანამედროვე სტილი.','ვარ მიუნხენის „ბაიერნის“ კაპიტანი და ორჯერ მაქვს მოგებული „ტრებლი“ (2013 და 2020 წლებში).','მანუელ ნოიერი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ალბასეტეში დავიწყე, სანამ 12 წლის ასაკში ცნობილ საფეხბურთო აკადემიაში მოვხვდებოდი.','2009 წელს ჩემპიონთა ლიგის ნახევარფინალში „ჩელსის“ კარში 93-ე წუთზე გადამწყვეტი გოლი გავიტანე.','2010 წლის მსოფლიო ჩემპიონატის ფინალში დამატებით დროში გამარჯვების გოლი გავიტანე ნიდერლანდების კარში.','ვარ ესპანელი ნახევარმცველი, რომელმაც კარიერის უდიდესი ნაწილი „ბარსელონაში“ ჩავისთან ერთად გაატარა.','ანდრეს ინიესტა',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „საუთჰემპტონის“ აკადემიაში დავიწყე, სადაც თავდაპირველად მარცხენა მცველის პოზიციაზე ვთამაშობდი.','2013 წელს იმ დროისთვის სარეკორდო თანხად ლონდონის „ტოტენჰემიდან“ ესპანეთში გადავედი.','2018 წლის ჩემპიონთა ლიგის ფინალში „ლივერპულის“ კარში ულამაზესი „მაკრატელა“ გოლი გავიტანე.','უელსის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი ვარ და 2016 წელს ნაკრები ევროპის ჩემპიონატის ნახევარფინალში გავიყვანე.','გარეთ ბეილი',true),
  ('მარტივი','Football','ფეხბურთელი','ფრანგული „ლილისა“ და „ჩელსის“ რიგებში თამაშის შემდეგ, 2019 წელს ესპანურ გრანდში გადავედი.','2018 წლის მსოფლიო ჩემპიონატზე ბელგიის ნაკრებთან ერთად ბრინჯაოს მედალი მოვიპოვე და ტურნირის „ვერცხლის ბურთი“ დავიმსახურე.','ლონდონის „ჩელსიში“ შვიდი სეზონი გავატარე, ორჯერ მოვიგე პრემიერ ლიგა და ორჯერ დავსახელდი კლუბის წლის საუკეთესო ფეხბურთელად.','კარიერა მადრიდის „რეალში“ გატარებული ტრავმებით სავსე პერიოდის შემდეგ, 2023 წელს დავასრულე.','ედენ აზარი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ფრანგულ „მონაკოში“ დავიწყე, სადაც არსენ ვენგერის ხელმძღვანელობით საფრანგეთის ჩემპიონი გავხდი.','2003–04 წლების სეზონში პრემიერ ლიგა დაუმარცხებლად მოვიგე და 30 გოლით ტურნირის ბომბარდირი გავხდი.','საფრანგეთის ეროვნულ ნაკრებთან ერთად მოვიგე 1998 წლის მსოფლიო ჩემპიონატი და 2000 წლის ევროპის ჩემპიონატი.','ლონდონის „არსენალის“ ყველა დროის საუკეთესო ბომბარდირი ვარ (228 გოლი) და სტადიონ „ემირეითსის“ წინ ჩემი ძეგლი დგას.','ტიერი ანრი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ფრანგულ „კანში“ დავიწყე, სანამ „ბორდოსა“ და ტურინის „იუვენტუსში“ ვითამაშებდი.','1998 წლის მსოფლიო ჩემპიონატის ფინალში ბრაზილიის კარში ორი თავური გოლი გავიტანე და იმავე წელს „ოქროს ბურთი“ მოვიგე.','2002 წლის ჩემპიონთა ლიგის ფინალში ლევერკუზენის „ბაიერის“ კარში ულამაზესი გოლი გავიტანე მარცხენა ფეხით ჰაერიდან.','მადრიდის „რეალის“ მთავარი მწვრთნელის რანგში ზედიზედ სამჯერ მოვიგე ჩემპიონთა ლიგა (2016, 2017, 2018).','ზინედინ ზიდანი',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპაში გადმოსვლის შემდეგ ვითამაშე ნიდერლანდურ „პსვ ეინდჰოვენსა“ და „ბარსელონაში“, სანამ იტალიაში გადავიდოდი.','2002 წლის მსოფლიო ჩემპიონატზე 8 გოლი გავიტანე, მათ შორის დუბლი გერმანიასთან ფინალში, და ტურნირის ბომბარდირი გავხდი.','ორჯერ მაქვს მოგებული „ოქროს ბურთი“ (1997 და 2002 წლებში), ხოლო 1997 წელს გავხდი ამ ჯილდოს ყველაზე ახალგაზრდა მფლობელი ისტორიაში.','ვარ ბრაზილიელი თავდამსხმელი, რომელსაც „ფენომენს“ (Il Fenomeno) ეძახიან და მითამაშია როგორც „ინტერსა“ და „მილანში“, ისე „ბარსელონასა“ და „რეალში“.','რონალდო',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „ლივერპულის“ აკადემიაში დავიწყე და 18 წლის ასაკში, 1998 წლის მსოფლიო ჩემპიონატზე არგენტინას ულამაზესი გოლი გავუტანე.','2001 წელს „ლივერპულთან“ ერთად უეფას თასი მოვიგე და იმავე წელს გავხდი ბოლო ინგლისელი ფეხბურთელი, რომელმაც „ოქროს ბურთი“ მოიპოვა.','საკლუბო დონეზე მითამაშია მადრიდის „რეალში“, „ნიუკასლ იუნაიტედსა“ და „მანჩესტერ იუნაიტედში“.','ინგლისის ეროვნულ ნაკრებში 89 მატჩში 40 გოლი გავიტანე.','მაიკლ ოუენი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა შვედურ „მალმიოში“ დავიწყე, საიდანაც ამსტერდამის „აიაქსში“ გადავედი.','ჩემი საკლუბო კარიერის განმავლობაში ვითამაშე იტალიის სამივე გრანდში — „იუვენტუსში“, „ინტერსა“ და „მილანში“.','2012 წელს ინგლისის ნაკრების კარში დაახლოებით 30 მეტრიდან ულამაზესი „მაკრატელა“ გოლი გავიტანე და პუშკაშის ჯილდო მოვიგე.','ვარ შვედეთის ეროვნული ნაკრების ყველა დროის საუკეთესო ბომბარდირი (62 გოლი).','ზლატან იბრაჰიმოვიჩი',true),
  ('მარტივი','Football','ფეხბურთელი','მთელი საკლუბო კარიერა მხოლოდ ერთ გუნდში გავატარე და 1985 წელს 16 წლის ასაკში მქონდა დებიუტი სერია A-ში.','საკლუბო დონეზე ჩემპიონთა თასი/ლიგა ხუთჯერ მაქვს მოგებული (1989, 1990, 1994, 2003, 2007).','იტალიის ეროვნულ ნაკრებში 126 მატჩი ჩავატარე და ვითამაშე ოთხ მსოფლიო ჩემპიონატზე.','„მილანის“ ლეგენდარული კაპიტანი და მცველი ვარ, რომლის 3-ნომრიანი მაისური კლუბმა სამუდამოდ ამოიღო ხმარებიდან.','პაოლო მალდინი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა გერმანულ „ვერდერში“ დავიწყე, ხოლო 2010 წელს მადრიდის „რეალში“ გადავედი.','2014 წელს გერმანიის ეროვნულ ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი.','პრემიერ ლიგაში 7 სეზონზე მეტი გავატარე ლონდონის „არსენალში“ და ოთხჯერ მოვიგე ინგლისის ასოციაციის თასი.','ვარ გერმანელი გამთამაშებელი, რომელიც მოედანზე გენიალური ხედვითა და საგოლე გადაცემებით გამოირჩეოდა.','მესუთ ოზილი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ლონდონის „ტოტენჰემის“ აკადემიაში დავიწყე და რამდენიმე გუნდში იჯარით ვითამაშე, სანამ ძირითად შემადგენლობაში დავმკვიდრდებოდი.','პრემიერ ლიგაში გატანილი 213 გოლით ტურნირის ისტორიაში მეორე საუკეთესო ბომბარდირი ვარ ალან შირერის შემდეგ.','2023 წელს გერმანულ „ბაიერნში“ გადავედი და პირველივე სეზონში ბუნდესლიგის 36 გოლით ევროპის „ოქროს ბუცი“ მოვიგე.','ვარ ინგლისის ეროვნული ნაკრების კაპიტანი და ყველა დროის საუკეთესო ბომბარდირი.','ჰარი კეინი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ბრაზილიურ „ფლამენგოში“ დავიწყე, ხოლო 2018 წელს, 18 წლის ასაკში მადრიდის „რეალს“ შევუერთდი.','გამარჯვების გოლები მაქვს გატანილი 2022 და 2024 წლების ჩემპიონთა ლიგის ფინალებში.','2024 წელს ფიფას ვერსიით მსოფლიოს საუკეთესო ფეხბურთელად (The Best) დამასახელეს.','ვარ ბრაზილიელი მარცხენა გარემარბი, რომელიც მადრიდის „რეალში“ 7- ნომრიანი მაისურით თამაშობს.','ვინისიუს ჟუნიორი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ინგლისურ „ბირმინგემ სიტიში“ დავიწყე, სადაც ჩემი წასვლის შემდეგ კლუბმა 22-ნომრიანი მაისური ხმარებიდან ამოიღო.','სამი სეზონი გავატარე დორტმუნდის „ბორუსიაში“, სადაც 2022–23 წლების სეზონში ბუნდესლიგის საუკეთესო ფეხბურთელი გავხდი.','2023 წელს მადრიდის „რეალში“ გადავედი, პირველივე სეზონში მოვიგე ლა ლიგა და ჩემპიონთა ლიგა, ხოლო „ელ კლასიკოებში“ გამარჯვების გოლები გავიტანე.','ვარ ინგლისის ნაკრების ნახევარმცველი, რომელსაც გოლის აღნიშვნისას ხელების ფართოდ გაშლა სჩვევია.','ჯუდ ბელინგემი',true),
  ('მარტივი','Football','ფეხბურთელი','ესპანეთის ლა ლიგაში დებიუტი 2023 წლის აპრილში, 15 წლისა და 290 დღის ასაკში მქონდა, რითაც „ბარსელონას“ ისტორიაში ყველაზე ახალგაზრდა დებიუტანტი გავხდი.','2024 წლის ევროპის ჩემპიონატზე გავხდი ტურნირის ისტორიაში ყველაზე ახალგაზრდა ფეხბურთელი, რომელმაც ითამაშა, გოლი გაიტანა და ჩემპიონი გახდა.','2024 წელს მოვიგე „კოპას ტროფეი“ (Kopa Trophy) და „Golden Boy“-ს ჯილდო, როგორც მსოფლიოს საუკეთესო ახალგაზრდა ფეხბურთელმა.','ვარ „ბარსელონასა“ და ესპანეთის ნაკრების მარჯვენა გარემარბი.','ლამინ იამალი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა პორტუგალიურ „მარიტიმუში“ დავიწყე, საიდანაც „პორტუში“ გადავედი და 2004 წელს ჩემპიონთა ლიგის გამარჯვებული გუნდის წევრი ვიყავი.','10 სეზონი გავატარე მადრიდის „რეალში“, სადაც სერხიო რამოსთან ერთად დაცვის ცენტრში ვთამაშობდი და სამჯერ მოვიგე ჩემპიონთა ლიგა.','2016 წელს პორტუგალიის ეროვნულ ნაკრებთან ერთად ევროპის ჩემპიონი გავხდი და ფინალის საუკეთესო მოთამაშედ დამასახელეს.','ვარ ბრაზილიაში დაბადებული პორტუგალიელი მცველი, რომელიც 41 წლის ასაკამდე თამაშობდა უმაღლეს დონეზე.','პეპე',true),
  ('მარტივი','Football','ფეხბურთელი','საკლუბო კარიერის სტარტზე თბილისის „დინამოში“, „ლოკომოტივსა“ და „რუსთავში“ ვთამაშობდი.','2024 წლის ევროპის ჩემპიონატზე პორტუგალიასთან ისტორიულ მატჩში 11 სეივი შევასრულე და ტურნირის ერთ-ერთ მთავარ აღმოჩენად ვიქეცი.','2024 წლის „ოქროს ბურთის“ დაჯილდოებაზე მსოფლიოს საუკეთესო მეკარეების სიაში (იაშინის ჯილდო) მე-7 ადგილი დავიკავე.','ვარ საქართველოს ეროვნული ნაკრების პირველი მეკარე, რომელმაც ესპანური „ვალენსიას“ შემდეგ კონტრაქტი ინგლისურ „ლივერპულთან“ გააფორმა.','გიორგი მამარდაშვილი',true),
  ('მარტივი','Football','ფეხბურთელი','საფრანგეთში დავიბადე და კარიერა ფრანგულ „მეცში“ დავიწყე, სადაც 2022–23 წლების სეზონში ლიგა 2-ის საუკეთესო ფეხბურთელი და ბომბარდირი გავხდი.','2024 წლის ევროპის ჩემპიონატზე ჯგუფურ ეტაპზე სამივე მატჩში გავიტანე გოლი (თურქეთთან, ჩეხეთთან და პორტუგალიასთან) და ტურნირის თანაბომბარდირი გავხდი.','2024 წელს დავბრუნდი მშობლიური ქალაქის კლუბში — ფრანგულ „ლიონში“.','ვარ საქართველოს ეროვნული ნაკრების თავდამსხმელი და გოლეადორი.','გიორგი მიქაუტაძე',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ბრაზილიურ „ფლუმინენსეში“ დავიწყე, ხოლო 2007 წელს, 18 წლის ასაკში მადრიდის „რეალში“ გადავედი.','მადრიდის „რეალის“ მაისურით 25 ტიტული მოვიგე, მათ შორის ხუთჯერ ჩემპიონთა ლიგა, და კლუბის კაპიტანიც ვიყავი.','2023 წელს მშობლიურ „ფლუმინენსესთან“ ერთად კოპა ლიბერტადორესიც მოვიგე.','ვარ ბრაზილიელი მარცხენა მცველი, რომელიც ხუჭუჭა თმითა და საოცარი ტექნიკით გამოირჩეოდა.','მარსელო',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ნიდერლანდურ „გრონინგენში“ დავიწყე, ხოლო შემდეგ „სელტიკსა“ და „საუთჰემპტონში“ ვითამაშე.','2018 წლის იანვარში იმ დროისთვის მცველისთვის სარეკორდო თანხად, 75 მილიონ ფუნტად „ლივერპულში“ გადავედი.','2019 წელს უეფას წლის საუკეთესო ფეხბურთელად დამასახელეს, ხოლო „ოქროს ბურთის“ გამოკითხვაში მეორე ადგილი დავიკავე.','ვარ ნიდერლანდების ეროვნული ნაკრებისა და „ლივერპულის“ კაპიტანი და ცენტრალური მცველი.','ვირჯილ ვან დეიკი',true),
  ('მარტივი','Football','ფეხბურთელი','მთელი პროფესიონალური საკლუბო კარიერა მხოლოდ ერთ გუნდში გავატარე და 2008 წელს 19 წლის ასაკში მქონდა დებიუტი.','„ბარსელონასთან“ ერთად მოვიგე 9 ლა ლიგა, 3 ჩემპიონთა ლიგა, ხოლო ესპანეთის ნაკრებთან ერთად 2010 წლის მსოფლიო და 2012 წლის ევროპის ჩემპიონატი.','ვარ მცველი, რომელიც 2018 წლამდე მომღერალ შაკირასთან ერთად ცხოვრობდა.','„ბარსელონას“ ლეგენდარული 3-ნომრიანი ცენტრალური მცველი ვარ, რომელმაც კარიერა 2022 წელს დაასრულა.','ჟერარ პიკე',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ბელგიურ „გენკში“ დავიწყე, ხოლო შემდეგ მადრიდის „ატლეტიკოსა“ და ლონდონის „ჩელსიში“ ვთამაშობდი.','2018 წლის მსოფლიო ჩემპიონატზე ბელგიის ნაკრებთან ერთად ბრინჯაოს მედალი მოვიპოვე და ტურნირის საუკეთესო მეკარის „ოქროს ხელთათმანი“ მოვიგე.','2022 წლის ჩემპიონთა ლიგის ფინალში „ლივერპულის“ წინააღმდეგ 9 სეივი შევასრულე და მატჩის საუკეთესო ფეხბურთელი გავხდი.','ვარ თითქმის 2 მეტრი სიმაღლის ბელგიელი მეკარე, რომელიც მადრიდის „რეალის“ კარს იცავს.','ტიბო კურტუა',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ესპანურ „ვილიარეალში“ დავიწყე, ხოლო შემდეგ მადრიდის „ატლეტიკოში“ ვითამაშე, სანამ პრემიერ ლიგაში გადავიდოდი.','2023 წლის ჩემპიონთა ლიგის ფინალში მილანის „ინტერის“ კარში ერთადერთი და გამარჯვების გოლი გავიტანე.','2024 წელს ესპანეთის ნაკრებთან ერთად ევროპის ჩემპიონი გავხდი და ტურნირის საუკეთესო ფეხბურთელად დამასახელეს.','2024 წელს მოვიგე „ოქროს ბურთი“ და „მანჩესტერ სიტის“ ნახევარდაცვის მთავარი საყრდენი ვარ.','როდრი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა არგენტინულ „ინდეპენდიენტეში“ დავიწყე და 2006 წელს მადრიდის „ატლეტიკოში“ გადავედი, სადაც უეფას ევროპა ლიგა მოვიგე.','2012 წელს პრემიერ ლიგის ბოლო ტურის 94-ე წუთზე გატანილი გოლით ჩემს კლუბს 44-წლიანი პაუზის შემდეგ ინგლისის ჩემპიონობა მოვუტანე.','ვარ „მანჩესტერ სიტის“ ყველა დროის საუკეთესო ბომბარდირი 260 გოლით.','ვარ არგენტინელი თავდამსხმელი, რომელსაც მეტსახელად „კუნს“ (Kun) ეძახიან და რომელმაც კარიერა 2021 წელს „ბარსელონაში“ გულის პრობლემების გამო დაასრულა.','სერხიო აგუერო',true),
  ('მარტივი','Football','ფეხბურთელი','საკლუბო კარიერის სტარტზე შვეიცარიულ „ბაზელსა“ და ავსტრიულ „ზალცბურგში“ ვთამაშობდი, სანამ პრემიერ ლიგაში გადავიდოდი.','2015 წელს „საუთჰემპტონის“ მაისურით „ასტონ ვილას“ კარში ჰეთ-თრიკი 2 წუთსა და 56 წამში შევასრულე, რაც პრემიერ ლიგის რეკორდია.','2022 წელს „ოქროს ბურთის“ გამოკითხვაში მეორე ადგილი დავიკავე და სენეგალის ნაკრებს აფრიკის ერთა თასი მოვაგებინე.','„ლივერპულის“ ლეგენდარული შემტევი ტრიოს წევრი ვიყავი მოჰამედ სალაჰთან და რობერტო ფირმინოსთან ერთად.','სადიო მანე',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ნიდერლანდურ „გრონინგენსა“ და „პსვ ეინდჰოვენში“ დავიწყე, სანამ ლონდონის „ჩელსიში“ გადავიდოდი.','2010 წლის მსოფლიო ჩემპიონატის ფინალში ესპანეთის მეკარე იკერ კასილასთან ერთი-ერთზე გავედი, მაგრამ გოლის გატანა ვერ მოვახერხე.','2013 წლის ჩემპიონთა ლიგის ფინალში 89-ე წუთზე დორტმუნდის „ბორუსიას“ კარში გამარჯვების გოლი გავიტანე.','ვარ ნიდერლანდელი მარჯვენა გარემარბი, რომელიც „ბაიერნში“ ფრანკ რიბერისთან ერთად „Robbery“-ს დუეტს ქმნიდა და მარცხენა ფეხით საფირმო დარტყმებით იყო ცნობილი.','არიენ რობენი',true),
  ('მარტივი','Football','ფეხბურთელი','პროფესიონალური კარიერა ფრანგულ „ბულონსა“ და „მეცში“ დავიწყე, ხოლო სახელი მარსელის „ოლიმპიკში“ გავითქვი.','2006 წლის მსოფლიო ჩემპიონატზე საფრანგეთის ნაკრებთან ერთად ფინალში ვითამაშე და ვერცხლის მედალი მოვიპოვე.','2013 წელს „ბაიერნთან“ ერთად „ტრებლი“ მოვიგე, უეფას წლის საუკეთესო ფეხბურთელად დამასახელეს და „ოქროს ბურთის“ გამოკითხვაში მე-3 ადგილი დავიკავე.','ვარ ფრანგი მარცხენა გარემარბი, რომელმაც მიუნხენის „ბაიერნში“ 12 სეზონი გაატარა და 9-ჯერ მოიგო ბუნდესლიგა.','ფრანკ რიბერი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა გერმანულ „ნიურნბერგსა“ და „დორტმუნდის ბორუსიაში“ დავიწყე, სადაც 2013 წელს ჩემპიონთა ლიგის ფინალში გოლი გავიტანე.','„მანჩესტერ სიტიში“ შვიდი სეზონი გავატარე, ხუთჯერ მოვიგე პრემიერ ლიგა და 2023 წელს გუნდს კაპიტნის სამკლავურით ჩემპიონთა ლიგა მოვაგებინე.','2023–24 წლების სეზონი „ბარსელონაში“ გავატარე, ხოლო შემდეგ კვლავ მანჩესტერში დავბრუნდი.','ვარ გერმანიის ეროვნული ნაკრების ყოფილი კაპიტანი და ცენტრალური ნახევარმცველი.','ილქაი გიუნდოგანი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ესპანურ „ბარსელონა B“-ში დავიწყე, ხოლო 2013 წელს პეპ გვარდიოლას მოთხოვნით მიუნხენის „ბაიერნში“ გადავედი.','კარიერის განმავლობაში ჩემპიონთა ლიგა ორ სხვადასხვა კლუბთან ერთად მაქვს მოგებული — „ბარსელონასა“ (2011) და „ბაიერნთან“ (2020) ერთად.','2020 წლიდან 2024 წლამდე ინგლისურ „ლივერპულში“ ვთამაშობდი.','ვარ ესპანელი ნახევარმცველი, რომელიც საოცარი ტექნიკითა და პასის კულტურით გამოირჩეოდა.','ტიაგო ალკანტარა',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა კოლუმბიურ „ენვიგადოში“ დავიწყე, ხოლო ევროპაში „პორტუსა“ და „მონაკოს“ რიგებში ვითამაშე.','2014 წლის მსოფლიო ჩემპიონატზე 6 გოლი გავიტანე, ტურნირის „ოქროს ბუცი“ მოვიგე და ურუგვაის კარში გატანილი გოლით პუშკაშის ჯილდო დავიმსახურე.','2014 წლის ზაფხულში მადრიდის „რეალში“ გადავედი, სადაც ორჯერ მოვიგე ჩემპიონთა ლიგა.','ვარ კოლუმბიის ეროვნული ნაკრების კაპიტანი და 2024 წლის კოპა ამერიკის საუკეთესო ფეხბურთელი.','ხამეს როდრიგესი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „სან-პაულუს“ აკადემიაში დავიწყე, ხოლო 2013 წელს მადრიდის „რეალში“ გადავედი.','მადრიდის „რეალში“ ლუკა მოდრიჩთან და ტონი კროოსთან ერთად ფეხბურთის ისტორიაში ერთ-ერთ ყველაზე წარმატებულ ნახევარდაცვის ტრიოს ვქმნიდი.','ხუთჯერ მაქვს მოგებული ჩემპიონთა ლიგა, ხოლო 2022 წელს „მანჩესტერ იუნაიტედში“ გადავედი.','ვარ ბრაზილიელი საყრდენი ნახევარმცველი, რომელიც 2019 წელს კოპა ამერიკის გამარჯვებულიც გახდა.','კაზემირო',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა მიუნხენის „ბაიერნში“ დავიწყე, ხოლო 2014 წელს მსოფლიო ჩემპიონატის მოგების შემდეგ მადრიდის „რეალში“ გადავედი.','კარიერის განმავლობაში ექვსჯერ მაქვს მოგებული ჩემპიონთა ლიგა — ერთხელ „ბაიერნთან“ და ხუთჯერ „რეალთან“ ერთად.','მოედანზე ყოველთვის თეთრი ფერის ბუცებით ვთამაშობდი და უზუსტესი გრძელი პასებით გამოვირჩეოდი.','საფეხბურთო კარიერა 2024 წლის ევროპის ჩემპიონატის შემდეგ დავასრულე, თანაც მაშინ, როცა კვლავ მსოფლიოს საუკეთესო ფორმაში ვიყავი.','ტონი კროოსი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერის უდიდესი ნაწილი მიუნხენის „ბაიერნში“ გავატარე და 2009 წელს იურგენ კლინსმანის ხელმძღვანელობით მქონდა დებიუტი.','2010 წლის მსოფლიო ჩემპიონატზე 5 გოლი გავიტანე და ტურნირის „ოქროს ბუცი“ და საუკეთესო ახალგაზრდა ფეხბურთელის ჯილდო მოვიპოვე.','2014 წელს გერმანიის ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი და მუნდიალებზე ჯამში 10 გოლი მაქვს გატანილი.','ვარ გერმანელი შემტევი, რომელსაც იუმორის გრძნობისა და სივრცის პოვნის უნარის გამო „Raumdeuter“-ს (სივრცის მკვლევარს) ეძახიან.','თომას მიულერი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ბრაზილიურ „ინტერნასიონალში“ დავიწყე, ხოლო ევროპაში პირველად იტალიურ „რომაში“ გადავედი.','2019 წელს მოვიგე იაშინის პირველი ჯილდო, როგორც მსოფლიოს საუკეთესო მეკარემ.','2021 წლის მაისში „ვესტ ბრომვიჩის“ კარში 95-ე წუთზე თავური გოლი გავიტანე და „ლივერპულს“ ჩემპიონთა ლიგის საგზური მოვუტანე.','ვარ ბრაზილიის ეროვნული ნაკრებისა და „ლივერპულის“ მთავარი მეკარე.','ალისონ ბეკერი',true),
  ('მარტივი','Football','ფეხბურთელი','ევროპული კარიერა პორტუგალიაში, „რიუ ავესა“ და ლისაბონის „ბენფიკაში“ გავატარე, სანამ ინგლისში გადავიდოდი.','პრემიერ ლიგაში ზედიზედ სამჯერ (2020, 2021, 2022) მოვიგე „ოქროს ხელთათმანი“.','ვარ გინესის რეკორდსმენი ფეხბურთის ბურთის ყველაზე შორ მანძილზე (75.35 მეტრი) ხელით ან ფეხით (drop-kick) დარტყმაში.','ვარ ბრაზილიელი მეკარე, რომელმაც „მანჩესტერ სიტისთან“ ერთად ექვსჯერ მოიგო პრემიერ ლიგა და 2023 წელს ჩემპიონთა ლიგა.','ედერსონი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა საფრანგეთში, „კანში“ დავიწყე, სანამ 2015 წელს ინგლისურ „ლესტერ სიტიში“ გადავიდოდი.','2016 წელს სენსაციურად მოვიგე პრემიერ ლიგა „ლესტერთან“ ერთად, ხოლო მომდევნო წელს ტიტული ლონდონის „ჩელსისთან“ ერთად დავიცავი.','2018 წელს საფრანგეთის ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი.','ვარ თავმდაბალი და ულევი ენერგიის მქონე ფრანგი საყრდენი ნახევარმცველი, რომელზეც ხუმრობით ამბობენ, რომ დედამიწის 70% წყლითაა დაფარული, დანარჩენი 30% კი — მისით.','ნ''გოლო კანტე',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ესპანურ „რეალ სოსიედადში“ დავიწყე, რადგან საფრანგეთის აკადემიებმა პატარა აღნაგობის გამო დამიწუნეს.','მადრიდის „ატლეტიკოს“ ისტორიაში ყველაზე მეტი გოლი მაქვს გატანილი და კლუბის ყველა დროის საუკეთესო ბომბარდირი ვარ.','2018 წელს საფრანგეთის ეროვნულ ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი და ფინალში გოლიც გავიტანე.','ვარ ფრანგი შემტევი, რომელიც გოლის აღნიშვნისას თამაშ „Fortnite“-ის ცნობილ ცეკვას ასრულებდა.','ანტუან გრიზმანი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა იტალიურ „ბრეშაში“ დავიწყე, სადაც რობერტო ბაჯოსთან ერთად ვთამაშობდი, ხოლო შემდეგ 10 წელი „მილანში“ გავატარე.','2006 წელს იტალიის ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი და ფინალში გოლის საგოლე გადაცემაც შევასრულე.','2012 წლის ევროპის ჩემპიონატზე ინგლისის ნაკრებს პენალტების სერიაში ლეგენდარული „პანენკა“ გავუტანე.','ვარ იტალიელი გამთამაშებელი, რომელიც საჯარიმო დარტყმების ოსტატობითა და წვერით გამოირჩეოდა, მეტსახელად კი „მაესტროს“ ეძახდნენ.','ანდრეა პირლო',true),
  ('მარტივი','Football','ფეხბურთელი','მთელი საკლუბო კარიერა მხოლოდ ერთ კლუბში გავატარე და 1993 წელს 16 წლის ასაკში მქონდა დებიუტი სერია A-ში.','2006 წელს იტალიის ეროვნულ ნაკრებთან ერთად მსოფლიო ჩემპიონი გავხდი.','სერია A-ში 250 გოლი მაქვს გატანილი და ყველა დროის ბომბარდირთა სიაში მეორე ადგილზე ვარ სილვიო პიოლას შემდეგ.','ვარ „რომას“ ლეგენდარული კაპიტანი და „რომის იმპერატორად“ წოდებული 10-ნომრიანი შემტევი.','ფრანჩესკო ტოტი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ინგლისურ „ვესტ ჰემ იუნაიტედში“ დავიწყე, ხოლო 2001 წელს ლონდონის სხვა კლუბში გადავედი.','პრემიერ ლიგის ისტორიაში ყველაზე შედეგიანი ნახევარმცველი ვარ 177 გატანილი გოლით.','ვარ „ჩელსის“ ყველა დროის საუკეთესო ბომბარდირი (211 გოლი).','ვარ ინგლისის ეროვნული ნაკრების ყოფილი ნახევარმცველი, რომელიც მოგვიანებით „ჩელსისა“ და „ევერტონის“ მთავარი მწვრთნელიც იყო.','ფრენკ ლემპარდი',true),
  ('მარტივი','Football','ფეხბურთელი','მთელი ინგლისური კარიერა მხოლოდ ერთ კლუბში გავატარე და 1998 წელს მქონდა დებიუტი პირველ გუნდში.','2005 წლის ჩემპიონთა ლიგის ფინალში „მილანთან“ ქამბექი ჩემი თავური გოლით დაიწყო.','ინგლისის პრემიერ ლიგის მოგება კარიერაში ვერასდროს მოვახერხე, თუმცა მოვიგე ჩემპიონთა ლიგა, უეფას თასი და ასოციაციის თასები.','ვარ „ლივერპულის“ ლეგენდარული კაპიტანი და 8-ნომრიანი ნახევარმცველი.','სტივენ ჯერარდი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ფრანგულ „ლე მანსა“ და „მარსელში“ დავიწყე, სანამ 2004 წელს ინგლისის პრემიერ ლიგაში გადავიდოდი.','2012 წლის ჩემპიონთა ლიგის ფინალში 88-ე წუთზე ანგარიში გავათანაბრე, შემდეგ კი პენალტების სერიაში გადამწყვეტი დარტყმა გავიტანე.','ორჯერ დამასახელეს აფრიკის წლის საუკეთესო ფეხბურთელად და კოტ- დ''ივუარის ნაკრების ყველა დროის საუკეთესო ბომბარდირი ვარ.','ლონდონის „ჩელსის“ ლეგენდარული თავდამსხმელი ვარ, რომელმაც კლუბთან ერთად ოთხჯერ მოიგო პრემიერ ლიგა.','დიდიე დროგბა',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „მანჩესტერ იუნაიტედის“ აკადემიაში დავიწყე და ცნობილი „Class of 92“-ის წევრი ვიყავი.','საფეხბურთო სამყაროში განთქმული ვიყავი საჯარიმო დარტყმებისა და ჩაწოდებების ოსტატობით.','2003 წელს მადრიდის „რეალში“ გადავედი, ხოლო შემდეგ ვითამაშე „ლოს- ანჯელეს გალაქსიში“, „მილანსა“ და „პარი სენ-ჟერმენში“.','ვარ ინგლისის ნაკრების ყოფილი კაპიტანი, რომელიც ამჟამად ამერიკული კლუბის, „ინტერ მაიამის“ თანამფლობელია.','დევიდ ბექჰემი',true),
  ('მარტივი','Football','ფეხბურთელი','პროფესიონალური კარიერა ფრანგულ „რენსა“ და „ბორდოში“ დავიწყე, სანამ 2004 წელს ინგლისურ კლუბში გადავიდოდი.','ინგლისის პრემიერ ლიგაში ყველაზე მეტი, 202 „მშრალი“ მატჩი მაქვს ჩატარებული.','2006 წელს მძიმე თავის ტრავმა მივიღე, რის შემდეგაც მთელი დარჩენილი კარიერა სპეციალური დამცავი ჩაფხუტით ვითამაშე.','ვარ ჩეხეთის ეროვნული ნაკრების ლეგენდარული მეკარე, რომელმაც კარიერის უდიდესი ნაწილი ლონდონის „ჩელსიში“ გაატარა.','პეტრ ჩეხი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა მადრიდის „რეალის“ აკადემიაში დავიწყე და 1999 წელს 18 წლის ასაკში მქონდა დებიუტი პირველ გუნდში.','2010 წელს ესპანეთის ეროვნულ ნაკრებს მსოფლიო ჩემპიონატზე ვუკაპიტნე და ფინალში არიენ რობენის ლეგენდარული დარტყმა ფეხით მოვიგერიე.','მადრიდის „რეალის“ მაისურით 725 მატჩი ჩავატარე და სამჯერ მოვიგე ჩემპიონთა ლიგა.','ვარ ესპანელი მეკარე, რომელსაც გულშემატკივრებმა „წმინდა იკერი“ (San Iker) შეარქვეს.','იკერ კასილასი',true),
  ('მარტივი','Football','ფეხბურთელი','საკლუბო კარიერა „ბარსელონაში“ დავიწყე და 2014 წელს გუნდის კაპიტნის რანგში დავასრულე კარიერა.','ესპანეთის ეროვნულ ნაკრებთან ერთად მოვიგე 2008 წლის ევროპისა და 2010 წლის მსოფლიო ჩემპიონატები, სადაც გერმანიას ნახევარფინალში თავური გოლი გავუტანე.','მოედანზე გამოვირჩეოდი გრძელი ხუჭუჭა თმით, შეუპოვარი ხასიათითა და სამართლიანი თამაშის პრინციპების დაცვით.','ვარ „ბარსელონას“ ლეგენდარული 5-ნომრიანი მცველი და კაპიტანი.','კარლეს პუიოლი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა არგენტინულ „არხენტინოს ხუნიორსში“ დავიწყე, სანამ „ბოკა ხუნიორსსა“ და „ბარსელონაში“ გადავიდოდი.','1986 წლის მსოფლიო ჩემპიონატის მეოთხედფინალში ინგლისის კარში ორი ისტორიული გოლი გავიტანე — ერთი ხელით, მეორე კი „საუკუნის გოლად“ აღიარებული სოლო რეიდით.','იტალიურ „ნაპოლის“ ისტორიაში პირველად მოვაგებინე ორი სკუდეტო და ქალაქის სტადიონს დღეს ჩემი სახელი ჰქვია.','ვარ არგენტინული ფეხბურთის ლეგენდა, რომელიც 10-ნომრიანი მაისურით თამაშობდა და 2020 წელს გარდაიცვალა.','დიეგო მარადონა',true),
  ('მარტივი','Football','ფეხბურთელი','მთელი პროფესიონალური კარიერის უდიდესი ნაწილი ბრაზილიურ „სანტოსში“ გავატარე, კარიერის ბოლოს კი ნიუ-იორკის „კოსმოსში“ ვითამაშე.','1958 წელს, 17 წლის ასაკში, გავხდი ყველაზე ახალგაზრდა ფეხბურთელი, რომელმაც მსოფლიო ჩემპიონატის ფინალში ითამაშა და გოლი გაიტანა.','ვარ ერთადერთი ფეხბურთელი ისტორიაში, რომელმაც მსოფლიო ჩემპიონატი სამჯერ მოიგო (1958, 1962, 1970).','ბრაზილიელი ლეგენდა ვარ, რომელსაც „ფეხბურთის მეფეს“ უწოდებენ.','პელე',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ნიდერლანდურ „აიაქსში“ დავიწყე და კლუბთან ერთად ზედიზედ სამჯერ მოვიგე ჩემპიონთა თასი (1971–1973).','1974 წლის მსოფლიო ჩემპიონატზე „ტოტალური ფეხბურთის“ მთავარი ვარსკვლავი ვიყავი და სწორედ იქ შევასრულე ჩემი სახელობის ცნობილი ფინტი.','სამჯერ მაქვს მოგებული „ოქროს ბურთი“ (1971, 1973, 1974).','ვიყავი ლეგენდარული 14-ნომრიანი ფეხბურთელი და მოგვიანებით „ბარსელონას“ მთავარი მწვრთნელი, რომელმაც კლუბს 1992 წელს პირველი ჩემპიონთა თასი მოაგებინა.','იოჰან კრუიფი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ჩრდილოეთ ირლანდიურ „გლენტორანში“ დავიწყე, სანამ პრემიერ ლიგის არაერთ კლუბში ვითამაშებდი.','ვარ მცველი, რომელიც „მანჩესტერ იუნაიტედში“ ორ სხვადასხვა პერიოდში თამაშობდა და სამჯერ მოიგო პრემიერ ლიგა.','ჩრდილოეთ ირლანდიის ნაკრებში 100-ზე მეტი მატჩი ჩავატარე და 2016 წლის ევროპის ჩემპიონატზე ვითამაშე.','ვარ ჩრდილოეთ ირლანდიის ეროვნული ნაკრების ყოფილი ცენტრალური მცველი, რომელმაც კარიერის ბოლოს „ლესტერთან“ ერთად ინგლისის ასოციაციის თასი მოიგო.','ჯონი ევანსი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „ლივერპულის“ აკადემიაში დავიწყე და მარჯვენა მცველის პოზიციაზე ვთამაშობ.','2019 წლის ჩემპიონთა ლიგის ნახევარფინალში „ბარსელონას“ კარში ლეგენდარული სწრაფი კუთხური ჩავაწოდე, რითაც დივოკ ორიჯიმ გადამწყვეტი გოლი გაიტანა.','პრემიერ ლიგის ისტორიაში მცველებს შორის ყველაზე მეტი საგოლე გადაცემა მაქვს შესრულებული.','ვარ ინგლისელი ფეხბურთელი, რომელიც „ლივერპულთან“ ერთად მოგებული ყველა დიდი ტიტულის შემდეგ მადრიდის „რეალს“ შეუერთდა.','ტრენტ ალექსანდერ-არნოლდი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „მანჩესტერ სიტის“ აკადემიაში დავიწყე და 2017 წელს 17 წლის ასაკში მქონდა დებიუტი პეპ გვარდიოლას ხელმძღვანელობით.','2023–24 წლების სეზონში პრემიერ ლიგის წლის საუკეთესო ფეხბურთელად დამასახელეს.','„მანჩესტერ სიტისთან“ ერთად ექვსჯერ მოვიგე ინგლისის ჩემპიონატი და 2023 წელს ჩემპიონთა ლიგა.','ვარ ინგლისელი შემტევი ნახევარმცველი, რომელსაც „სტოკპორტის ინიესტას“ ეძახიან და 47-ნომრიანი მაისურით თამაშობს.','ფილ ფოდენი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა „მანჩესტერ სიტის“ აკადემიაში დავიწყე, თუმცა 2023 წელს ლონდონურ კლუბში გადავედი, სადაც მთავარ ვარსკვლავად ვიქეცი.','2024 წლის ევროპის ჩემპიონატის ფინალში ესპანეთის კარში გოლი გავიტანე.','2024 წლის სექტემბერში „ბრაიტონის“ წინააღმდეგ პირველივე ტაიმში 4 გოლი გავიტანე, რაც პრემიერ ლიგის ისტორიაში პირველი შემთხვევაა.','ვარ ლონდონის „ჩელსის“ ინგლისელი ლიდერი, რომელიც გოლის აღნიშვნისას სიცივისგან კანკალის იმიტაციას აკეთებს („Cold“).','კოულ პალმერი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ნიდერლანდურ „აიაქსში“ დავიწყე, სადაც 2018–19 წლების სეზონში ჩემპიონთა ლიგის ნახევარფინალში გავედი.','2019 წელს „ბარსელონაში“ გადავედი და კლუბთან ერთად ლა ლიგა და ესპანეთის თასი მოვიგე.','ვარ ნიდერლანდების ეროვნული ნაკრების ძირითადი ცენტრალური ნახევარმცველი.','„ბარსელონაში“ 21-ნომრიანი მაისურით ვთამაშობ და ჩემი სახელი ხშირად ასოცირდება ბურთის საოცარ კონტროლთან და დრიბლინგთან.','ფრენკი დე იონგი',true),
  ('მარტივი','Football','ფეხბურთელი','კარიერა ესპანურ „ლას-პალმასში“ დავიწყე, ხოლო 2020 წელს კატალონიურ გრანდს შევუერთდი.','2021 წელს მოვიგე როგორც „Golden Boy“-ს ჯილდო, ისე „კოპას ტროფეი“.','2024 წელს ესპანეთის ეროვნულ ნაკრებთან ერთად ევროპის ჩემპიონი გავხდი.','ვარ „ბარსელონას“ 8-ნომრიანი ნახევარმცველი და კანარის კუნძულებზე ვარ დაბადებული.','პედრი',true),
